 C.cuisine=code=>({code,label:C.cuisineLabels[code]||'Food from '+(C.country(code)?.name||'a new place'),slot:C.extraStampArt[code]?.slot??C.stampArt.slots[code],dish:C.extraStampArt[code]?.dish||C.stampArt.dishes[code]||null,artPath:C.extraStampArt[code]?'more-food-atlas.png':C.stampArt.path});
 const names=new Intl.DisplayNames(['en'],{type:'region'});C.countries=C.countryCodes.split(' ').map(code=>({code,name:names.of(code)}));
 C.country=code=>C.countries.find(c=>c.code===code);
 C.rarityFor=code=>{const record=C.counts[code];if(!record||!Number.isInteger(record.count)||record.count<1)return {name:'Not assessed',rank:0,count:null,status:'unknown'};const tier=C.rarity.find(t=>record.count<=t.max);return {...tier,...record,label:record.status==='verified'?tier.name:'Demo '+tier.name}};
 C.earned=(state,spots)=>[...new Set(spots.filter(s=>state.visits[s.id]>0).flatMap(s=>s.countryCodes||[]))];
 C.rank=xp=>C.ranks.filter(r=>r.level<=1+Math.floor(xp/500)).at(-1).title;
 C.progress=(trail,state,spots)=>{const earned=C.earned(state,spots);let have,need,goal;if(trail.mode==='countries'){need=trail.codes.filter(c=>!earned.includes(c));goal=trail.codes.length;have=goal-need.length;}else if(trail.mode==='businesses'){need=trail.businessIds.filter(id=>!state.visits[id]);goal=trail.businessIds.length;have=goal-need.length;}else{let codes=earned;if(trail.mode==='theme-countries')codes=[...new Set(spots.filter(s=>state.visits[s.id]&&s.themeTags?.includes(trail.tag)).flatMap(s=>s.countryCodes))];goal=trail.goal;have=Math.min(goal,codes.length);need=spots.filter(s=>s.countryCodes.some(c=>!codes.includes(c))&&(trail.mode!=='theme-countries'||s.themeTags?.includes(trail.tag))).flatMap(s=>s.countryCodes);need=[...new Set(need)];}return {have,goal,missing:need,done:have>=goal};};
